nextflow_process {

    name "Test Process JELLYFISH_DUMP"
    script "../main.nf"
    config "./nextflow.config"
    process "JELLYFISH_DUMP"

    tag "modules"
    tag "modules_nfcore"
    tag "jellyfish"
    tag "jellyfish/dump"
    tag "jellyfish/count"

    setup {
        run("JELLYFISH_COUNT") {
            script "../../count/main.nf"

            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = 7
                input[2] = '100M'
                """
            }
        }
    }

    test("sarscov2 - fasta") {

        when {
            params {
                module_args = ""
            }
            process {
                """
                input[0] = JELLYFISH_COUNT.out.jf
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("sarscov2 - txt") {
        when {
            params {
                module_args = "-c"
            }
            process {
                """
                input[0] = JELLYFISH_COUNT.out.jf
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

    test("sarscov2 - fasta - stub") {

        options "-stub"

        when {
            params {
                module_args = ""
            }
            process {
                """
                input[0] = JELLYFISH_COUNT.out.jf
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

}
